import asyncio, json
from playwright.async_api import async_playwright

routes = ["/", "/clients", "/clients/cl-maya", "/clients/cl-maya/generate"]

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        for r in routes:
            page = await browser.new_page()
            errors = []
            page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
            page.on("pageerror", lambda e: errors.append(str(e)))
            url = "http://localhost:4175" + r
            try:
                await page.goto(url, wait_until="networkidle", timeout=15000)
            except Exception as e:
                print(json.dumps({"route": r, "goto_error": str(e)[:200]}))
                await page.close(); continue
            # mutation preflight
            mut = await page.evaluate("""() => {
                document.title = 'probe-' + Math.random().toString(36).slice(2,8);
                const s = document.createElement('script');
                document.head.appendChild(s);
                return {title: document.title, scripts: document.head.querySelectorAll('script').length};
            }""")
            # axe
            try:
                await page.add_script_tag(url="https://cdnjs.cloudflare.com/ajax/libs/axe-core/4.10.2/axe.min.js")
                axe = await page.evaluate("async () => { const r = await axe.run(document, {resultTypes:['violations']}); const agg = {}; for (const v of r.violations) { agg[v.id] = {impact: v.impact, count: v.nodes.length, example: v.nodes[0] ? v.nodes[0].target.join(' ') : ''}; } return agg; }")
            except Exception as e:
                axe = {"error": str(e)[:200]}
            print(json.dumps({"route": r, "mutation_title_readback": mut.get("title"), "axe": axe, "console_errors": len(errors), "console_error_samples": errors[:3]}))
            await page.close()
        await browser.close()

asyncio.run(main())
EOF
